import bz2
import collections
import marshal
import struct
import sys


def render(meta, bodies):
    first, width, start, step, modulus = meta
    return b''.join(str(first+i).zfill(width).encode()+b' '+body+b' '+str((start+i*step)%modulus).encode()+b'\n' for i,body in enumerate(bodies))


def compress(data):
    best = b'B' + bz2.compress(data)
    try:
        fields = [x.split(b' ',1) for x in data.splitlines()]
        bodies, suffixes = zip(*(rest.rsplit(b' ',1) for _,rest in fields))
        nums = list(map(int,suffixes))
        modulus = max(nums)+1
        meta = (int(fields[0][0]),len(fields[0][0]),nums[0],(nums[1]-nums[0])%modulus,modulus)
        if render(meta,bodies) != data:
            return best
        choices = []
        for period in range(1,17):
            defaults = [collections.Counter(bodies[j::period]).most_common(1)[0][0] for j in range(period)]
            count = sum(body == defaults[i%period] for i,body in enumerate(bodies))
            choices.append((count-period,defaults))
        defaults = max(choices,key=lambda x:x[0])[1]
        vocab = sorted(set(word for body in bodies for word in body.split(b' ')))
        if len(vocab)>255:
            return best
        ids = {word:i+1 for i,word in enumerate(vocab)}
        stream = bytearray()
        last = -1
        for i,body in enumerate(bodies):
            if body != defaults[i%len(defaults)]:
                stream.extend(struct.pack('>I',i-last))
